from typing import Dict, Type

def check_type_match(instance, type_alias):
    """Checks if the type of an instance matches a generic alias."""
    try:
        return isinstance(instance, type_alias)
    except TypeError:
        return False

# Example usage:
dict_instance = {"a": 1, "b": 2}
str_int_type = Dict[str, int]

print(check_type_match(dict_instance, str_int_type))
